-- Exported from project swiftborder (weatherforecast.v_weather_features_10min) on 2026-09-26 via INFORMATION_SCHEMA.TABLES.

CREATE OR REPLACE VIEW `swiftborder.weatherforecast.v_weather_features_10min`
AS WITH w AS (SELECT TIMESTAMP_SECONDS(DIV(UNIX_SECONDS(issue_timestamp), 600) * 600) AS bin_ts, forecast, REGEXP_CONTAINS(LOWER(forecast), r'rain|shower|thunder') AS rain_flag, REGEXP_CONTAINS(LOWER(forecast), r'heavy|thunder') AS heavy_flag FROM `swiftborder.weatherforecast.weatherforecast` WHERE LOWER(area) = 'woodlands'), r AS (SELECT TIMESTAMP_SECONDS(DIV(UNIX_SECONDS(timestamp), 600) * 600) AS bin_ts, AVG(value_mm) AS rain_mm FROM `swiftborder.rainfall.rainfall` WHERE station_id = 'Woodlands Centre Road' GROUP BY 1) SELECT COALESCE(w.bin_ts, r.bin_ts) AS bin_ts, MAX(CAST(w.rain_flag AS INT64)) AS wx_rain_nowcast, MAX(CAST(w.heavy_flag AS INT64)) AS wx_heavy_nowcast, ANY_VALUE(w.forecast) AS wx_forecast, AVG(r.rain_mm) AS wx_rain_mm FROM w FULL OUTER JOIN r USING (bin_ts) GROUP BY 1;
